/*
 * THE COACH WRITES TO A LEARNER (DBU-07): a reply, or the first word. role:staff is checked by
 * nodegx.security.json before this runs. The learner must be a learner (someone with a plan);
 * a message about a homework must be about one of hers that she can see (shared). Text only:
 * Richard's files reach a learner as homework resources (DBU-03).
 * Saved with mailPending; shared/Message mail tells the learner next, unless she turned it off.
 */
(async () => {
  const refuse = (why) => { Outputs.why = why; Outputs.refuse(); };
  try {
    const me = String(Inputs.userId || '');
    if (!me) throw new Error('no session user');
    const q = (c, where) => Noodl.Records.query(c, where, { limit: 1000, plain: true });
    const learnerId = String(Inputs.learnerId || '');
    const users = learnerId ? await q('_User', { objectId: { equalTo: learnerId } }) : [];
    const plans = users.length ? await q('Plan', { learner: { equalTo: learnerId } }) : [];
    if (!users.length || !plans.length || learnerId === me) return refuse('This learner could not be found. Reload the page.');

    const body = String(Inputs.body || '').trim();
    if (!body) return refuse('Write your message first.');
    if (body.length > 5000) return refuse('Keep a message under 5,000 characters, or send it in two.');

    const stepId = String(Inputs.stepId || '');
    if (stepId) {
      const steps = await q('Step', { objectId: { equalTo: stepId } });
      const step = steps[0];
      if (!step || step.learner !== learnerId || step.kind !== 'homework') return refuse('That homework is not in this learner\'s plan.');
      if (step.shared !== true) return refuse('Share that homework first: the learner cannot see it yet.');
    }

    const created = await Noodl.Records.create('Message', {
      learner: learnerId, author: me, step: stepId || null, body, attachments: [],
      readAt: null, mailPending: true, mailedAt: null
    }, { plain: true });
    await Noodl.Records.create('Doorbell', { learner: learnerId, topic: 'message' },
      { acl: { [learnerId]: { read: true }, 'role:staff': { read: true } } });

    Outputs.messageId = created.objectId || created.id;
    Outputs.mail = { learnerId, to: 'learner', at: Date.now() };
  } catch (e) {
    console.error('[dbu:replyAsCoach]', String((e && e.message) || e));
    Outputs.failed();
  }
})();
